def min_operations(a, b):
    a_factors, b_factors = prime_factors(a), prime_factors(b)
    a_ops, b_ops = 0, 0
    for f_a, f_b in zip(a_factors, b_factors):
        for k in range(1, f_a + 1):
            a_factor = f_a // k
            b_factor = f_b // k
            while a_factor > k:
                a_ops += 1
                a_factor //= k
            while b_factor > k:
                b_ops += 1
                b_factor //= k
            if a_factor == k * sqrt(a_factor) and b_factor == k:
                break
    return a_ops + b_ops

