from collections import defaultdict

def count_distinctive_roots(n, values, edges):
    parent = {i: i for i in range(1, n + 1)}
    rank = defaultdict(int)
    descendant_count = {i: 0 for i in range(1, n + 1)}

    def find(x):
        if x != parent[x]:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        rootX = find(x)
        rootY = find(y)
        if rootX != rootY:
            if rank[rootX] > rank[rootY]:
                rootY, rootX = rootX, rootY
            parent[rootX] = rootY
            rank[rootY] += 1

    for u, v in edges:
        union(u, v)

    def dfs(node, parent, visited_values):
        nonlocal distinctive_count
        for child in tree[node]:
            if child != parent and child not in visited_values:
                distinct_value = min(child, values[child - 1])
                visited_values.add(child)
                for node in visited_values:
                    distinct_value = max(node, distinct_value)
                    # Here we check if all values encountered in the path are distinct
                    parent_of_parent = find(child)
                    if distinct_value < tree[parent_of_parent][find(parent_of_parent)]:
                        return
                    intersection = False
                    for value in tree[node]:
                        if value in visited_values and value not in distinct_value:
                            intersection = True
                            break
                    if intersection:
                        distinct_value = max(max(tree[parent][find(parent)]), distinct_value)
                        # Recursively check the path from the top
                        dfs(parent, node, visited_values)

    distinctive_count = 0
    # Start DFS from each node to detect distinctive roots
    for i in range(1, n+1):
        tree = defaultdict(list)
        for parent, child in tree[i]:
            tree[find(child)] += [find(parent)]
        dfs(i, i, set())
    return distinctive_count

