from typing import List

def count_distinctive_roots(n: int, values: List[int], edges: List[List[int]]) -> int:
    # Build adjacency list
    adj_list = defaultdict(list)
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Depth-first search to count distinctive roots
    def dfs(node, parent, path_value, unique_values, subtree_size):
        if subtree_size < 1:
            return True
        if subtree_size > 1 or (unique_values > 0 and not unique_values == path_value):
            return False

        unique_values.add(path_value)
        for neighbor in adj_list[node]:
            if neighbor == parent:
                continue
            next_subtree_size = subtree_size - 1
            if dfs(neighbor, node, path_value, unique_values, next_subtree_size):
                return True
        return False

    distinctive_roots = 0
    for start_node in range(1, n + 1):
        unique_values = set()
        if dfs(start_node, -1, start_node, unique_values, n):
            distinctive_roots += 1

    return distinctive_roots
