def equal_divisors(a, b):
    a_primes = prime_factors(a)
    b_primes = prime_factors(b)
    a_factors = math.factorial(len(a_primes))
    b_factors = math.factorial(len(b_primes))

    if a_primes == b_primes:
        return 0
    elif len(a_primes) < len(b_primes):
        return len(a_primes) + len(b_primes) - len(b_primes)
    elif len(b_primes) < len(a_primes):
        return len(b_primes) + len(a_primes) - len(a_primes)

