from collections import defaultdict, deque

def bfs(start, end, graph):
    q = deque([start])
    visited = set([start])
    level = defaultdict(lambda: float('inf'))
    level[start] = 0
    while q:
        node = q.popleft()
        if node == end:
            return level[end]
        for neighbor in graph[node]:
            if neighbor not in visited:
                visited.add(neighbor)
                q.append(neighbor)
                level[neighbor] = level[node] + 1
    return None

def prepareGraph(binNum):
    graph = defaultdict(list)
    for i in range(2**binNum):
        for j in range(i+1, 2**binNum+1):
            diff = bin(i ^ j)
            diff = "".join(diff)
            prefix = binNum - 1 - len(diff)
            while (prefix):
                diff = '0' + diff[:prefix]
                prefix -= 1
            if diff:
                graph[(i, j)] = [int(diff)]
    return graph

