                path_values = set(values[child-1])
                for child_value in dfs(child, current):
                    path_values |= {child_value}
                    if len(path_values) < len(values[child]):
                        # Only add this child if it introduces distinct values
                        distinctive_roots += 1

    for root in roots:
        dfs(root, -1)

    return distinctive_roots

# Example usage
