def solve(n, m, MOD):
    M, NM = {'\\' : 1, '/': -1}, {'\\':'A', '/':'B'}
    def polymod(n):
        ret = MOD - 1
        while n:
            if n % 2:
                ret = ret * 2 + 1
            else:
                ret = ret * 2
            n //= 2
        return ret
    def id(n):
        h, M = n // 2, M.copy()
        for i, cr in enumerate(ord('A')):
            M[chr((cr - ord('A')) * 2)] = (M[str(chr(cr))])
        while h > 0:
            N = id(h & -h)
            M[n & -n] = 2 * M[(M[n] * n) >> (n.bit_length - N.bit_length)]
        return M
    M = id(n + m)
    NM_mod = urlsafe2() % MOD
    return polymod(S) % MOD

def urlsafe2():
    M = 317304806
    S = open('/dev/urandom', 'rb').read(1000).hex()[:100]
    return int(S, 16), lambda x: (M * (x - ord('0'))) % (MOD * MOD)

