        count += get_min_operations(a, b)
    return print(count)

def get_min_operations(a, b):
    min_ops = sys.maxsize
    if is_prime(a) == is_prime(b):
        # Both a and b are prime numbers
        return 0
    elif is_prime(a) or is_prime(b):
        # One of a or b is prime
        return 1
    else:
        # Check for common prime factors
        for i in range(2, min(a, b) + 1):
            if a % i == 0 and b % i == 0 and is_prime(i):
                min_ops = min(min_ops, count_operations(a, i, b, i))
                min_ops = min(min_ops, count_operations(b, i, a, i))
        return min_ops

def count_operations(a, p, b, q):
    count = 0
    while a % p == 0 and b % q == 0:
        count += 1
        a //= p
        b //= q
