        elif v != graph[u][-1]:
            white_edges.append((u, -u))
    factor = 2
    carry_over = 0
    same_amount_edges = len(black_edges)
    while len(black_edges) < len(white_edges):
        factor_given = factor % same_amount_edges
        carry_over_given = (same_amount_edges - factor_given) // 2
        if (len(black_edges) - factor_given) % 2 == carry_over:
            black_edges.extend([(u, v - u) for u, v in black_edges])
            black_edges.extend([(u, v + (u - graph[u][-1])) for u, v in white_edges])
            white_edges = []
            factor *= 2
            carry_over *= 2
        else:
