def num_ideals(x):
    n = 0
    ideals = []
    bit_length = 0

    while x > 0:
        if x & 1:
            ideals.append('1')
            if n > 1:
                n -= 2
            bit_length += 1
        else:
            while x & 1 == 0:
                x >>= 1
                if n > 1:
                    n -= 2
            bit_length += 1
        x >>= 1

    if n == 0:
        return 1 if bit_length == 0 else 0
    else:
        return pow(2, bit_length - bit_length % 2, 1000000007) * pow(3, bit_length // 2, 1000000007) % 1000000007

def shortest_ideal(x):
